import os
from typing import Any, Dict, List, Optional

from openai import OpenAI


class TextSafetyModeration:
    def __init__(
        self,
        api_key: Optional[str] = None,
        model: str = "omni-moderation-latest",
    ) -> None:
        self.client = OpenAI(api_key=api_key or os.environ["OPENAI_API_KEY"])
        self.model = model

    def analyze(self, text: str) -> Dict[str, Any]:
        response = self.client.moderations.create(
            model=self.model,
            input=text,
        )
        result = response.results[0]
        categories = {}
        if getattr(result, "categories", None):
            categories = {
                key: bool(value)
                for key, value in result.categories.model_dump().items()
            }
        category_scores = {}
        if getattr(result, "category_scores", None):
            category_scores = {
                key: float(value)
                for key, value in result.category_scores.model_dump().items()
            }
        flagged = bool(getattr(result, "flagged", False))
        return {
            "flagged": flagged,
            "categories": categories,
            "category_scores": category_scores,
            "unsafe_spans": self._infer_unsafe_spans(text, categories, category_scores, flagged),
        }

    def redact(self, text: str, replacement: str = "[REDACTED]") -> Dict[str, Any]:
        analysis = self.analyze(text)
        spans = analysis["unsafe_spans"]
        if not spans:
            return {
                "flagged": analysis["flagged"],
                "redacted_text": text,
                "unsafe_spans": [],
                "categories": analysis["categories"],
                "category_scores": analysis["category_scores"],
            }

        merged = self._merge_spans(spans)
        redacted_parts: List[str] = []
        last = 0
        for span in merged:
            start = span["start"]
            end = span["end"]
            redacted_parts.append(text[last:start])
            redacted_parts.append(replacement)
            last = end
        redacted_parts.append(text[last:])

        return {
            "flagged": analysis["flagged"],
            "redacted_text": "".join(redacted_parts),
            "unsafe_spans": merged,
            "categories": analysis["categories"],
            "category_scores": analysis["category_scores"],
        }

    def _infer_unsafe_spans(
        self,
        text: str,
        categories: Dict[str, bool],
        category_scores: Dict[str, float],
        flagged: bool,
    ) -> List[Dict[str, Any]]:
        spans: List[Dict[str, Any]] = []
        lower = text.lower()

        keyword_map = {
            "hate": ["slur", "subhuman", "exterminate", "inferior race", "kill all"],
            "hate/threatening": ["lynch", "hang them", "burn them alive"],
            "harassment": ["idiot", "moron", "stupid", "worthless"],
            "harassment/threatening": ["i will kill you", "i'll kill you", "break your neck", "shoot you"],
            "self-harm": ["suicide", "kill myself", "end my life", "self-harm"],
            "self-harm/intent": ["i want to die", "i will kill myself", "i'm going to kill myself"],
            "self-harm/instructions": ["best way to kill yourself", "how to commit suicide"],
            "sexual": ["explicit sex", "nude child", "sexual act", "porn"],
            "sexual/minors": ["underage sex", "child porn", "minor nude"],
            "violence": ["murder", "stab", "shoot", "behead", "dismember"],
            "violence/graphic": ["guts spilled", "graphic gore", "blood everywhere", "decapitated"],
        }

        active_categories = {
            name
            for name, is_true in categories.items()
            if is_true or category_scores.get(name, 0.0) >= 0.5
        }

        for category in active_categories:
            for phrase in keyword_map.get(category, []):
                start = 0
                while True:
                    idx = lower.find(phrase, start)
                    if idx == -1:
                        break
                    spans.append(
                        {
                            "start": idx,
                            "end": idx + len(phrase),
                            "label": category,
                            "text": text[idx:idx + len(phrase)],
                        }
                    )
                    start = idx + 1

        if not spans and flagged and text.strip():
            spans.append(
                {
                    "start": 0,
                    "end": len(text),
                    "label": "flagged_content",
                    "text": text,
                }
            )

        return spans

    def _merge_spans(self, spans: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not spans:
            return []

        ordered = sorted(spans, key=lambda x: (x["start"], x["end"]))
        merged: List[Dict[str, Any]] = [ordered[0].copy()]

        for span in ordered[1:]:
            current = merged[-1]
            if span["start"] <= current["end"]:
                current["end"] = max(current["end"], span["end"])
                labels = set(str(current.get("label", "")).split("|")) | set(str(span.get("label", "")).split("|"))
                current["label"] = "|".join(sorted(label for label in labels if label))
            else:
                merged.append(span.copy())

        for item in merged:
            item.pop("text", None)

        return merged
